-- =====================================================================
-- YIQ — question bank : pool separation + the competition question set
-- Created 2026-08-24. Fixes the two defects flagged in the header of
-- yiq_03_seed_papers.sql.
--
-- DEFECT 1 — mock and real papers drew from the SAME questions, so a
-- student who practised had already seen the real paper. Every question
-- now carries a `pool`:
--     practice     may be drawn ONLY by a mock paper
--     competition  may be drawn ONLY by a real (scored) paper
--     either       may be drawn by both  [default]
-- The column is the data half of the guard; the decision half is
-- lib/yiq/question-pools.ts (eligiblePools / assertPoolSafe), which fails
-- CLOSED on an unknown paper kind or an unknown pool value.
--
-- DEFECT 2 — the bank held only the 33 deck questions. This migration
-- adds 195 competition-only questions across all 7 topics.
--
-- NO NEW TABLE is created here, so no new grants are required: yiq_00
-- already granted service_role on yiq.questions and a new COLUMN inherits
-- the table's privileges. (Tables added through the Management API get no
-- default grants — see the GRANTS block at the end of yiq_00.)
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. the pool column
-- ---------------------------------------------------------------------
alter table yiq.questions
  add column if not exists pool text not null default 'either';

alter table yiq.questions
  drop constraint if exists yiq_questions_pool_valid;

alter table yiq.questions
  add constraint yiq_questions_pool_valid
  check (pool in ('practice','competition','either'));

comment on column yiq.questions.pool is
  'Which papers may draw this question: practice = mock only, competition = '
  'scored rounds only, either = both. A competition paper must NEVER draw a '
  'practice question. Enforced in lib/yiq/question-pools.ts.';

create index if not exists yiq_questions_pool_lookup
  on yiq.questions (pool, is_active, is_retired, category);

-- ---------------------------------------------------------------------
-- 2. the 33 deck questions are BURNED for competition use
--
-- They are verbatim from the Director's deck (YIQ.pptx, slides 8-11),
-- which circulates to chapters and schools ahead of the round. Anyone who
-- has read the deck has read the answers, so they cannot be used to
-- separate one team from another. They move to the practice pool, where
-- being known is not a problem — that is exactly what a mock paper is for.
-- ---------------------------------------------------------------------
update yiq.questions
   set pool = 'practice'
 where source = 'YIQ deck 2026 (sample questions)'
   and pool <> 'practice';

-- ---------------------------------------------------------------------
-- 3. what happened to the four self-dated deck questions
--
-- yiq_01_seed deliberately left four deck questions unseeded because they
-- go stale. None of them enters the competition pool as written; each is
-- either replaced by a permanently-true rephrasing or dropped.
--
--   (a) "Who holds the record for most ODI centuries?"  — the deck answers
--       Sachin Tendulkar (49); Virat Kohli passed that mark in 2023, so
--       the answer moves.
--       REPLACED BY "Who was the first cricketer to score 100 international
--       centuries?" (Sachin Tendulkar). A first-to-reach fact can be
--       equalled but never overtaken.
--
--   (b) "India's rank in the 2024 Paris Olympics medal tally?" — the deck
--       itself says "to be updated annually".
--       REPLACED BY "Which city hosted the 2024 Summer Olympic Games?"
--       (Paris). Same subject, no moving number.
--
--   (c) "Which Indian won the 2024 Nobel Prize (if any)?" — the deck itself
--       says "updated each year", and in some years the honest answer is
--       nobody.
--       DROPPED, not rephrased. Three settled Nobel facts stand in its
--       place in this set: Kailash Satyarthi (Peace 2014), Mother Teresa
--       (Peace 1979) and Venkatraman Ramakrishnan (Chemistry 2009). No
--       "latest winner" question exists in the competition pool.
--
--   (d) "Who is the current Governor of the RBI?" — the deck answers
--       Sanjay Malhotra "as of 2025"; it changes with every appointment.
--       REPLACED BY two permanent questions: the FIRST Governor of the RBI
--       (Sir Osborne Smith) and the first INDIAN Governor (C. D. Deshmukh).
--
-- The same discipline applies to the whole set below: no current
-- office-holder, no "latest" anything, no current ranking, no
-- most-recent-winner. Anything that would need re-checking before the next
-- cycle was left out rather than guessed.
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- 4. the competition set — 195 questions, 27-30 per topic
--
-- Text is dollar-quoted so apostrophes need no escaping. Each insert is
-- guarded on question_text, so this file is safe to re-run. The correct
-- option is spread almost exactly evenly across a/b/c/d (49/49/49/48) and
-- placed by hash order, so neither the position nor the sequence of
-- positions carries a hint.
-- ---------------------------------------------------------------------

-- india

-- young-india-leadership

-- business-economics

-- science-technology

-- current-affairs

-- sports

-- arts-culture

-- ---------------------------------------------------------------------
-- 5. after this migration
--
-- The papers built by yiq_03_seed_papers.sql attached EVERY active MCQ to
-- both the mock and the online-round paper, which is the leak this file
-- exists to close. Adding the column does not un-attach them: those papers
-- must be REBUILT from the admin console (Build paper) so each one draws
-- only from its eligible pools. Deliberately not done here — rewriting
-- another migration's paper rows would be a silent data change.
-- ---------------------------------------------------------------------

do $report$
declare
  n_practice integer;
  n_comp integer;
  n_either integer;
begin
  select count(*) into n_practice from yiq.questions where pool = 'practice';
  select count(*) into n_comp     from yiq.questions where pool = 'competition';
  select count(*) into n_either   from yiq.questions where pool = 'either';
  raise notice 'yiq.questions by pool -> practice: %, competition: %, either: %',
    n_practice, n_comp, n_either;
  if n_comp = 0 then
    raise warning 'No competition questions: real papers would fall back to nothing.';
  end if;
end;
$report$;
